#!/bin/bash
# SPDX-License-Identifier: Apache-2.0
# SPDX-FileCopyrightText: 2026 Signal Slot, Inc.
#
#   tools/cts/deqp-limits-tally-selftest.sh
#
# Host-only check of `deqp-limits-tally.py --require-pass limits` on the
# fixture runs in tools/cts/fixtures/deqp-limits-tally/ (synthetic, not a dEQP
# result): all limit cases Pass (exit 0), one Fail (exit 3), one case missing
# from the run (exit 3). The selected names come from gles3-mustpass.txt; the
# fixtures are regenerated by fixtures/deqp-limits-tally/mk.py. Also checks
# that the default output is not changed by the option's existence.
set -u

HERE=$(dirname "$0")
TALLY=$HERE/deqp-limits-tally.py
FIX=$HERE/fixtures/deqp-limits-tally
fail=0
pass=0
ok()  { printf '  ok    %s\n' "$1"; pass=$((pass + 1)); }
bad() { printf '  FAIL  %s\n' "$1"; fail=$((fail + 1)); }
chk() { local l=$1; shift; if "$@"; then ok "$l"; else bad "$l"; fi; }
# rc <command...>: the exit status
rc() { "$@" >/dev/null 2>&1; echo $?; }
req() { python3 -I "$TALLY" --require-pass limits "$@"; }

N=$(grep -cE '^dEQP-GLES3\.functional\.(implementation_limits|state_query\.(integers|integers64|floats|booleans))\.max_(varying_(vectors|components)|fragment_input_components|vertex_output_components|uniform_block_size|combined_(vertex|fragment)_uniform_components)(_get(boolean|float|integer|integer64))?$' "$HERE/gles3-mustpass.txt")
chk "mustpass holds limit cases ($N)" test "$N" -gt 0

out=$(req "$FIX/allpass"); r=$?
chk "all pass: exit 0" test "$r" = 0
chk "all pass: summary '$N selected, $N pass, 0 not-pass'" \
    test "$(printf '%s\n' "$out" | tail -n1)" = "$N selected, $N pass, 0 not-pass"
chk "all pass: one line per case" test "$(printf '%s\n' "$out" | grep -c '^Pass dEQP-GLES3')" = "$N"
chk "all pass: names are mustpass names" \
    test "$(printf '%s\n' "$out" | grep '^Pass ' | cut -d' ' -f2 | LC_ALL=C sort | LC_ALL=C comm -23 - <(LC_ALL=C sort "$HERE/gles3-mustpass.txt") | wc -l)" = 0

out=$(req "$FIX/onefail"); r=$?
chk "one fail: exit non-zero" test "$r" != 0
chk "one fail: a Fail line" test "$(printf '%s\n' "$out" | grep -c '^Fail ')" = 1
chk "one fail: summary" test "$(printf '%s\n' "$out" | tail -n1)" = "$N selected, $((N - 1)) pass, 1 not-pass"

out=$(req "$FIX/missing"); r=$?
chk "missing: exit non-zero" test "$r" != 0
chk "missing: a Missing line" test "$(printf '%s\n' "$out" | grep -c '^Missing ')" = 1
chk "missing: summary" test "$(printf '%s\n' "$out" | tail -n1)" = "$N selected, $((N - 1)) pass, 1 not-pass"

chk "two runs, one bad: exit non-zero" test "$(rc python3 -I "$TALLY" --require-pass limits "$FIX/allpass" "$FIX/onefail")" != 0
chk "two runs both good: exit 0" test "$(rc python3 -I "$TALLY" --require-pass limits "$FIX/allpass" "$FIX/allpass")" = 0
chk "no run: refused" test "$(rc python3 -I "$TALLY" --require-pass limits)" = 2
chk "with --compare: refused" test "$(rc python3 -I "$TALLY" --compare --require-pass limits "$FIX/allpass" "$FIX/onefail")" = 2
chk "default output has no verdict lines" \
    test "$(python3 -I "$TALLY" "$FIX/allpass" | grep -c 'selected,')" = 0
chk "tally --selftest still passes" python3 -I "$TALLY" --selftest >/dev/null

printf '%d ok, %d failed\n' "$pass" "$fail"
[ "$fail" = 0 ]
